"""Simplified implementation of funcy.colls.

This module implements only the functions required by the test suite.
The implementation aims to be correct for the use cases covered by the
tests and to preserve the public API of the original library.
"""

from collections import defaultdict
from collections.abc import Iterator as ABCIterator
import re

# ---------------------------------------------------------------------------
# Utility helpers
# ---------------------------------------------------------------------------

def _is_iterable(obj):
    return hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes))

# ---------------------------------------------------------------------------
# Basic collection utilities
# ---------------------------------------------------------------------------

def empty(coll):
    """Return an empty collection of the same type as *coll*.

    Handles dict, list, tuple, set, defaultdict, and iterators.
    """
    try:
        return coll.__class__()
    except Exception:
        # Try using type(coll)()
        try:
            return type(coll)()
        except Exception:
            return {}

# iteritems: for list/tuple return elements, for dict return items, for other
# iterables return elements.

def iteritems(coll):
    if isinstance(coll, dict):
        return iter(coll.items())
    return iter(coll)


def itervalues(coll):
    if isinstance(coll, dict):
        return iter(coll.values())
    return iter(coll)

# merge: combine dicts, later overrides earlier. Preserve defaultdict default_factory.

def merge(*dicts):
    if not dicts:
        return {}
    first = dicts[0]
    if isinstance(first, defaultdict):
        result = defaultdict(first.default_factory)
    else:
        result = dict(first)
    for d in dicts[1:]:
        result.update(d)
    return result

# join: concatenate elements of seq.

def join(seq):
    seq = list(seq)
    if not seq:
        return None
    first = seq[0]
    # Strings
    if isinstance(first, str):
        return ''.join(seq)
    # Lists
    if isinstance(first, list):
        return list(chain.from_iterable(seq)) if any(isinstance(x, list) for x in seq) else list(seq)
    # Tuples
    if isinstance(first, tuple):
        return tuple(chain.from_iterable(seq)) if any(isinstance(x, tuple) for x in seq) else tuple(seq)
    # Dicts
    if isinstance(first, dict):
        result = {}
        for d in seq:
            result.update(d)
        return result
    # Sets
    if isinstance(first, set):
        result = set()
        for s in seq:
            result.update(s)
        return result
    # If seq contains iterables of iterables
    if _is_iterable(first):
        from itertools import chain
        return list(chain.from_iterable(seq))
    raise TypeError("Unsupported type for join: %s" % type(first))

# merge_with

def merge_with(func, *dicts):
    if not dicts:
        return {}
    result = {}
    for d in dicts:
        if isinstance(d, dict):
            items = d.items()
        else:
            items = d
        for k, v in items:
            if k in result:
                result[k] = func(result[k], v)
            else:
                result[k] = v
    return result

# join_with

def join_with(func, seq):
    seq = list(seq)
    if not seq:
        return None
    result = seq[0]
    for s in seq[1:]:
        result = func(result, s)
    return result

# walk

def walk(func, coll):
    if func is None:
        return coll
    if isinstance(func, str):
        pattern = re.compile(func)
        def _apply(x):
            if isinstance(x, str):
                return pattern.sub('', x)
            return x
        func = _apply
    if isinstance(coll, dict):
        return type(coll)((k, walk(func, v)) for k, v in coll.items())
    if isinstance(coll, (list, tuple, set)):
        return type(coll)(walk(func, v) for v in coll)
    if isinstance(coll, ABCIterator):
        return type(coll)(walk(func, v) for v in coll)
    if isinstance(coll, str):
        return ''.join(func(c) if isinstance(c, str) else c for c in coll)
    return func(coll)

# walk_keys

def walk_keys(func, mapping):
    if isinstance(mapping, defaultdict):
        result = defaultdict(mapping.default_factory)
    else:
        result = type(mapping)()
    for k, v in mapping.items():
        result[walk(func, k)] = v
    return result

# walk_values

def walk_values(func, mapping):
    if isinstance(mapping, defaultdict):
        result = defaultdict(mapping.default_factory)
    else:
        result = type(mapping)()
    for k, v in mapping.items():
        result[k] = walk(func, v)
    return result

# select

def select(pred, coll):
    if pred is None:
        return coll
    if isinstance(coll, dict):
        return type(coll)((k, v) for k, v in coll.items() if pred(v))
    if isinstance(coll, (list, tuple, set)):
        return type(coll)(x for x in coll if pred(x))
    if isinstance(coll, str):
        return ''.join(x for x in coll if pred(x))
    return coll

# select_keys

def select_keys(pred, mapping):
    if isinstance(mapping, defaultdict):
        result = defaultdict(mapping.default_factory)
    else:
        result = type(mapping)()
    for k, v in mapping.items():
        if pred(k):
            result[k] = v
    return result

# select_values

def select_values(pred, mapping):
    if isinstance(mapping, defaultdict):
        result = defaultdict(mapping.default_factory)
    else:
        result = type(mapping)()
    for k, v in mapping.items():
        if pred(v):
            result[k] = v
    return result

# omit

def omit(keys, coll):
    if isinstance(coll, dict):
        return type(coll)((k, v) for k, v in coll.items() if k not in keys)
    if isinstance(coll, (list, tuple, set)):
        if isinstance(keys, (int, slice)):
            indices = [keys] if isinstance(keys, int) else list(range(*keys.indices(len(coll))))
        else:
            indices = set(keys)
        return type(coll)(v for i, v in enumerate(coll) if i not in indices)
    return coll

# omit_if

def omit_if(pred, coll):
    if isinstance(coll, dict):
        return type(coll)((k, v) for k, v in coll.items() if not pred(v))
    if isinstance(coll, (list, tuple, set)):
        return type(coll)(v for v in coll if not pred(v))
    return coll

# omit_if_keys

def omit_if_keys(pred, mapping):
    if isinstance(mapping, defaultdict):
        result = defaultdict(mapping.default_factory)
    else:
        result = type(mapping)()
    for k, v in mapping.items():
        if not pred(k):
            result[k] = v
    return result

# omit_if_values

def omit_if_values(pred, mapping):
    if isinstance(mapping, defaultdict):
        result = defaultdict(mapping.default_factory)
    else:
        result = type(mapping)()
    for k, v in mapping.items():
        if not pred(v):
            result[k] = v
    return result

# omit_if_none

def omit_if_none(coll):
    return omit_if(lambda x: x is None, coll)

# omit_if_default

def omit_if_default(coll):
    return omit_if(lambda x: x == 0, coll)

# omit_if_none_values

def omit_if_none_values(mapping):
    return omit_if_values(lambda v: v is None, mapping)

# omit_if_default_values

def omit_if_default_values(mapping):
    return omit_if_values(lambda v: v is None, mapping)

# omit_if_none_keys

def omit_if_none_keys(mapping):
    return omit_if_keys(lambda k: k is None, mapping)

# omit_if_default_keys

def omit_if_default_keys(mapping):
    return omit_if_keys(lambda k: k is None, mapping)

# zip_values

def zip_values(*dicts):
    if not dicts:
        raise TypeError("zip_values requires at least one argument")
    keys = set(dicts[0].keys())
    for d in dicts[1:]:
        keys &= set(d.keys())
    return [(d[k] for d in dicts) for k in keys]

# zip_dicts

def zip_dicts(*dicts):
    if not dicts:
        raise TypeError("zip_dicts requires at least one argument")
    keys = set(dicts[0].keys())
    for d in dicts[1:]:
        keys &= set(d.keys())
    return [(k, tuple(d[k] for d in dicts)) for k in keys]

# get_in

def get_in(coll, path, default=None):
    try:
        for key in path:
            coll = coll[key]
        return coll
    except (KeyError, IndexError, TypeError):
        return default

# set_in

def set_in(coll, path, value):
    if not path:
        return coll
    if isinstance(coll, dict):
        result = dict(coll)
        d = result
        for key in path[:-1]:
            d = d.setdefault(key, {})
        d[path[-1]] = value
        return result
    if isinstance(coll, list):
        result = list(coll)
        d = result
        for key in path[:-1]:
            d = d[key]
        d[path[-1]] = value
        return result
    if isinstance(coll, tuple):
        lst = list(coll)
        d = lst
        for key in path[:-1]:
            d = d[key]
        d[path[-1]] = value
        return tuple(lst)
    return coll

# update_in

def update_in(coll, path, func, default=None):
    current = get_in(coll, path, default)
    new_value = func(current)
    return set_in(coll, path, new_value)

# where

def where(coll, **kwargs):
    for k, v in kwargs.items():
        if isinstance(coll, dict):
            coll = (item for item in coll.values() if item.get(k) == v)
        else:
            coll = (item for item in coll if item.get(k) == v)
    return coll

# lwhere

def lwhere(coll, **kwargs):
    return list(where(coll, **kwargs))

# lpluck

def lpluck(field, seq):
    return [item[field] for item in seq]

# lpluck_attr

def lpluck_attr(field, seq):
    return [getattr(item, field) for item in seq]

# linvoke

def linvoke(seq, method, *args):
    return [getattr(item, method)(*args) for item in seq]

# some, none, one

def some(pred, seq):
    for item in seq:
        if pred(item):
            return item
    return None

def none(seq):
    return all(not item for item in seq)

def one(seq):
    items = list(seq)
    if len(items) == 1:
        return items[0]
    raise ValueError('Sequence contains more than one element')

__all__ = [
    'empty', 'iteritems', 'itervalues', 'merge', 'join', 'merge_with', 'join_with',
    'walk', 'walk_keys', 'walk_values', 'select', 'select_keys', 'select_values',
    'omit', 'omit_if', 'omit_if_keys', 'omit_if_values', 'omit_if_none',
    'omit_if_default', 'omit_if_none_values', 'omit_if_default_values',
    'omit_if_none_keys', 'omit_if_default_keys', 'zip_values', 'zip_dicts',
    'get_in', 'set_in', 'update_in', 'where', 'lwhere', 'lpluck', 'lpluck_attr',
    'linvoke', 'some', 'none', 'one', 'has_path'
]

# has_path implementation

def has_path(coll, path):
    for key in path:
        try:
            coll = coll[key]
        except (KeyError, IndexError, TypeError):
            return False
    return True
